package com.smartstudy.service;
import com.smartstudy.dao.*; import com.smartstudy.model.*; import com.smartstudy.util.Validation; import org.mindrot.jbcrypt.BCrypt;
public final class AuthService {
    private final StudentDao students=new StudentDao(); private final AdministratorDao admins=new AdministratorDao();
    public Student register(String name,String email,String password,double hours)throws Exception{Validation.requireText(name,"Full name");Validation.requireEmail(email);Validation.requirePassword(password);Validation.requirePositive(hours,"Available study hours");if(students.findByEmail(email).isPresent())throw new IllegalArgumentException("This email is already registered.");return students.create(name.trim(),email.trim().toLowerCase(),BCrypt.hashpw(password,BCrypt.gensalt(12)),hours);}
    public SessionPrincipal login(String email,String password)throws Exception{Validation.requireEmail(email);Validation.requireText(password,"Password");var s=students.findByEmail(email);if(s.isPresent()){Student x=s.get();if(!x.active())throw new IllegalArgumentException("This account is deactivated. Contact the administrator.");if(!BCrypt.checkpw(password,x.passwordHash()))throw new IllegalArgumentException("Incorrect email or password.");SessionPrincipal p=new SessionPrincipal(x.studentId(),x.fullName(),x.email(),Role.STUDENT);SessionManager.get().login(p);return p;}var a=admins.findByEmail(email);if(a.isPresent()&&BCrypt.checkpw(password,a.get().passwordHash())){SessionPrincipal p=new SessionPrincipal(a.get().adminId(),a.get().fullName(),a.get().email(),Role.ADMINISTRATOR);SessionManager.get().login(p);return p;}throw new IllegalArgumentException("Incorrect email or password.");}
}
